/* RPC Rounds Diagnostics Lab: instrument identification cards (drawings). Built by t34/inst.py */
var DXIC=[{"id": "i01", "cat": "Lid, speculum and fixation", "title": "Barraquer wire speculum", "fields": [{"k": "wirespec"}], "q": "Identify this instrument.", "o": ["Barraquer wire speculum", "Universal (adjustable) eye speculum", "Chalazion clamp", "Desmarres lid retractor"], "a": 0, "steps": ["How to recognise it: Light spring wire with two open loops that hook under the lids; no screw.", "Used for: Keeps the lids open in cataract, pterygium and injections.", "Viva: Why a wire speculum for injections? Light, cheap, leaves room; avoid pressure on the globe in open-globe injuries."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i02", "cat": "Lid, speculum and fixation", "title": "Universal (adjustable) eye speculum", "fields": [{"k": "solidspec"}], "q": "Identify this instrument.", "o": ["Universal (adjustable) eye speculum", "Jaeger lid plate", "Barraquer wire speculum", "Chalazion clamp"], "a": 0, "steps": ["How to recognise it: Two solid blades with a screw or ratchet to set the opening.", "Used for: Wider, fixed exposure in longer operations (keratoplasty, squint, retina).", "Viva: Disadvantage? Pressure on the globe raises IOP; avoid in open globe and in thin corneas."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i03", "cat": "Lid, speculum and fixation", "title": "Desmarres lid retractor", "fields": [{"k": "desmarres"}], "q": "Identify this instrument.", "o": ["Desmarres lid retractor", "Chalazion curette", "Jaeger lid plate", "Barraquer wire speculum"], "a": 0, "steps": ["How to recognise it: Handle with a curved, saddle-shaped plate at the end.", "Used for: Retracts the lid to examine a child's or swollen eye, or in lid surgery.", "Viva: Use in a child with a swollen lid? Gently, without pressure, to see the cornea and exclude a perforation."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i04", "cat": "Lid, speculum and fixation", "title": "Jaeger lid plate", "fields": [{"k": "misc", "t": "jaeger"}], "q": "Identify this instrument.", "o": ["Jaeger lid plate", "Universal (adjustable) eye speculum", "Chalazion curette", "Desmarres lid retractor"], "a": 0, "steps": ["How to recognise it: Broad, flat, slightly curved plate on a handle.", "Used for: Supports the lid and protects the globe during lid surgery (entropion, ptosis, lid tumours).", "Viva: Material? Usually stainless steel or horn; acts as a cutting board for the lid."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i05", "cat": "Lid, speculum and fixation", "title": "Chalazion clamp", "fields": [{"k": "chalazion"}], "q": "Identify this instrument.", "o": ["Chalazion clamp", "Jaeger lid plate", "Universal (adjustable) eye speculum", "Chalazion curette"], "a": 0, "steps": ["How to recognise it: A ring on one blade and a solid plate on the other, closed by a screw.", "Used for: Holds and everts the lid during incision and curettage of a chalazion; also stops bleeding.", "Viva: Which side goes where? Ring on the conjunctival side over the chalazion, plate on the skin side."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i06", "cat": "Lid, speculum and fixation", "title": "Chalazion curette", "fields": [{"k": "rod", "tip": "curette"}], "q": "Identify this instrument.", "o": ["Chalazion curette", "Barraquer wire speculum", "Jaeger lid plate", "Universal (adjustable) eye speculum"], "a": 0, "steps": ["How to recognise it: Small sharp-edged cup on a handle.", "Used for: Scoops out chalazion contents after a vertical tarsal incision.", "Viva: Why a vertical incision? Parallel to the meibomian glands, so fewer glands are cut."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i07", "cat": "Forceps", "title": "Plain (non-toothed) conjunctival forceps", "fields": [{"k": "forceps", "tip": "plain"}], "q": "Identify this instrument.", "o": ["Plain (non-toothed) conjunctival forceps", "Suture-tying forceps", "Kelman-McPherson IOL forceps", "Curved mosquito artery forceps"], "a": 0, "steps": ["How to recognise it: Fine tips with smooth inner surfaces, no teeth.", "Used for: Holds conjunctiva and delicate tissue without tearing.", "Viva: Why not toothed forceps on conjunctiva? Teeth tear thin conjunctiva and buttonhole it."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i08", "cat": "Forceps", "title": "Toothed (1×2) tissue forceps", "fields": [{"k": "forceps", "tip": "toothed"}], "q": "Identify this instrument.", "o": ["Toothed (1×2) tissue forceps", "Straight artery forceps", "Suture-tying forceps", "Kelman-McPherson IOL forceps"], "a": 0, "steps": ["How to recognise it: One tooth on one tip fits between two teeth on the other.", "Used for: Grips sclera, cornea, skin and tendon firmly (for example Lim, Bishop Harman).", "Viva: Why 1×2 teeth? They interlock to grip tough tissue without slipping."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i09", "cat": "Forceps", "title": "Colibri forceps", "fields": [{"k": "forceps", "tip": "colibri"}], "q": "Identify this instrument.", "o": ["Colibri forceps", "End-gripping (ILM) forceps", "Straight artery forceps", "Suture-tying forceps"], "a": 0, "steps": ["How to recognise it: Curved, very fine tips with tiny teeth, angled like a bird's beak.", "Used for: Fixation of the globe or cornea during corneal and cataract incisions.", "Viva: Name origin? Colibri means hummingbird: the curved shape resembles its beak."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i10", "cat": "Forceps", "title": "Suture-tying forceps", "fields": [{"k": "forceps", "tip": "tying"}], "q": "Identify this instrument.", "o": ["Suture-tying forceps", "McPherson angled forceps", "End-gripping (ILM) forceps", "Straight artery forceps"], "a": 0, "steps": ["How to recognise it: Smooth flat platforms at the tips, no teeth.", "Used for: Ties fine sutures (8-0 to 10-0) without cutting them.", "Viva: Why platforms? A broad smooth grip holds the thread without fraying it."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i11", "cat": "Forceps", "title": "McPherson angled forceps", "fields": [{"k": "forceps", "tip": "mcpherson"}], "q": "Identify this instrument.", "o": ["McPherson angled forceps", "Plain (non-toothed) conjunctival forceps", "Suture-tying forceps", "End-gripping (ILM) forceps"], "a": 0, "steps": ["How to recognise it: Smooth tips bent at an angle to the shaft.", "Used for: Tying sutures and handling tissue inside the eye or near the limbus.", "Viva: Advantage of the angle? Your hand stays out of the line of sight under the microscope."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i12", "cat": "Forceps", "title": "Utrata capsulorhexis forceps", "fields": [{"k": "forceps", "tip": "utrata"}], "q": "Identify this instrument.", "o": ["Utrata capsulorhexis forceps", "Bipolar cautery forceps", "Plain (non-toothed) conjunctival forceps", "Suture-tying forceps"], "a": 0, "steps": ["How to recognise it: Long fine shafts with short, sharp, bent tips.", "Used for: Grasps and tears the anterior capsule to make a continuous curvilinear capsulorhexis.", "Viva: Ideal rhexis size? About 5–5.5 mm, round, centred, overlapping the IOL optic edge."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i13", "cat": "Forceps", "title": "Kelman-McPherson IOL forceps", "fields": [{"k": "forceps", "tip": "kelman"}], "q": "Identify this instrument.", "o": ["Kelman-McPherson IOL forceps", "McPherson angled forceps", "Bipolar cautery forceps", "Plain (non-toothed) conjunctival forceps"], "a": 0, "steps": ["How to recognise it: Angled tips with grooved, smooth inner surfaces.", "Used for: Holds and inserts a rigid or folded IOL; manipulates the lens.", "Viva: Why smooth? To avoid scratching the optic."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i14", "cat": "Forceps", "title": "End-gripping (ILM) forceps", "fields": [{"k": "forceps", "tip": "ilm"}], "q": "Identify this instrument.", "o": ["End-gripping (ILM) forceps", "Toothed (1×2) tissue forceps", "McPherson angled forceps", "Bipolar cautery forceps"], "a": 0, "steps": ["How to recognise it: Very fine, small, end-opening jaws on a long thin shaft (23–27G).", "Used for: Peels the internal limiting membrane and epiretinal membranes in vitrectomy.", "Viva: Dyes used to stain ILM? Brilliant blue, ICG (low concentration) or trypan blue for ERM."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i15", "cat": "Forceps", "title": "Bipolar cautery forceps", "fields": [{"k": "forceps", "tip": "bipolar"}], "q": "Identify this instrument.", "o": ["Bipolar cautery forceps", "Curved mosquito artery forceps", "Toothed (1×2) tissue forceps", "McPherson angled forceps"], "a": 0, "steps": ["How to recognise it: Insulated forceps with two electrodes connected to a cable.", "Used for: Coagulates bleeding vessels on sclera and conjunctiva (wet-field cautery).", "Viva: Bipolar vs monopolar? Current passes only between the tips, so less spread and safer near the eye."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i16", "cat": "Forceps", "title": "Curved mosquito artery forceps", "fields": [{"k": "artery", "curved": 1}], "q": "Identify this instrument.", "o": ["Curved mosquito artery forceps", "Utrata capsulorhexis forceps", "Bipolar cautery forceps", "Toothed (1×2) tissue forceps"], "a": 0, "steps": ["How to recognise it: Ring handles, ratchet lock, short curved serrated jaws.", "Used for: Clamps small vessels; holds sutures and drapes in oculoplasty.", "Viva: Why the ratchet? It locks the jaws so the forceps stay closed."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i17", "cat": "Forceps", "title": "Straight artery forceps", "fields": [{"k": "artery"}], "q": "Identify this instrument.", "o": ["Straight artery forceps", "Colibri forceps", "Utrata capsulorhexis forceps", "Bipolar cautery forceps"], "a": 0, "steps": ["How to recognise it: Ring handles, ratchet lock and straight serrated jaws.", "Used for: Crushes tissue before cutting (for example canthotomy) and clamps vessels.", "Viva: Use in lateral canthotomy? Crush the canthus for 30 seconds to reduce bleeding, then cut."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i18", "cat": "Scissors and needle holders", "title": "Vannas capsulotomy scissors", "fields": [{"k": "sscissors", "tip": "scissorAngled"}], "q": "Identify this instrument.", "o": ["Vannas capsulotomy scissors", "Westcott tenotomy scissors", "Stevens tenotomy scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Spring-action handle with very fine angled blades.", "Used for: Cuts the capsule, iris (iridectomy) and fine membranes in the anterior chamber.", "Viva: Spring vs ring handle? Spring scissors give fine control with fingertip pressure."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i19", "cat": "Scissors and needle holders", "title": "Westcott tenotomy scissors", "fields": [{"k": "sscissors", "tip": "scissorCurved"}], "q": "Identify this instrument.", "o": ["Westcott tenotomy scissors", "Vannas capsulotomy scissors", "Stevens tenotomy scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Spring handle with curved, usually blunt-tipped blades.", "Used for: Cuts conjunctiva and Tenon's capsule in squint, pterygium and glaucoma surgery.", "Viva: Why blunt tips? Safer dissection under conjunctiva without buttonholing."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i20", "cat": "Scissors and needle holders", "title": "Corneal (Castroviejo) scissors", "fields": [{"k": "sscissors", "tip": "scissorCurved"}], "q": "Identify this instrument.", "o": ["Corneal (Castroviejo) scissors", "Vannas capsulotomy scissors", "Stevens tenotomy scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Spring handle with fine curved blades; made in right and left pairs.", "Used for: Enlarges corneal and corneoscleral incisions; cuts the graft in keratoplasty.", "Viva: Right and left scissors? Corneal scissors come in pairs to cut in each direction around a wound."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i21", "cat": "Scissors and needle holders", "title": "Iris (de Wecker or straight iris) scissors", "fields": [{"k": "rscissors", "tip": "scissorStraight"}], "q": "Identify this instrument.", "o": ["Iris (de Wecker or straight iris) scissors", "Vannas capsulotomy scissors", "Stevens tenotomy scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Small ring-handled scissors with straight sharp blades.", "Used for: Cuts iris, sutures and small tissue pieces.", "Viva: Peripheral iridectomy purpose? Bypasses pupil block in angle closure or after trabeculectomy."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i22", "cat": "Scissors and needle holders", "title": "Stevens tenotomy scissors", "fields": [{"k": "rscissors", "tip": "scissorCurved"}], "q": "Identify this instrument.", "o": ["Stevens tenotomy scissors", "Vannas capsulotomy scissors", "Iris (de Wecker or straight iris) scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Ring handles with short curved, blunt blades.", "Used for: Dissection in squint surgery and oculoplasty.", "Viva: Which way do the curves face? Usually towards the globe to follow its curvature."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i23", "cat": "Scissors and needle holders", "title": "Enucleation scissors", "fields": [{"k": "rscissors", "tip": "bluntCurved", "big": 1}], "q": "Identify this instrument.", "o": ["Enucleation scissors", "Vannas capsulotomy scissors", "Iris (de Wecker or straight iris) scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Large, strongly curved, blunt scissors with ring handles.", "Used for: Cuts the optic nerve behind the globe during enucleation.", "Viva: Length of optic nerve to take in retinoblastoma? As long as possible (over 10 mm) to check for tumour spread."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i24", "cat": "Scissors and needle holders", "title": "Barraquer needle holder", "fields": [{"k": "nholder", "tip": "needleCurved"}], "q": "Identify this instrument.", "o": ["Barraquer needle holder", "Vannas capsulotomy scissors", "Iris (de Wecker or straight iris) scissors", "Castroviejo needle holder"], "a": 0, "steps": ["How to recognise it: Spring handle without a lock; fine curved jaws.", "Used for: Holds fine needles (8-0 to 10-0) in corneal and limbal suturing.", "Viva: Why no lock? Allows smooth, quick needle release under the microscope."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i25", "cat": "Scissors and needle holders", "title": "Castroviejo needle holder", "fields": [{"k": "nholder", "tip": "needleStraight", "lock": 1}], "q": "Identify this instrument.", "o": ["Castroviejo needle holder", "Vannas capsulotomy scissors", "Iris (de Wecker or straight iris) scissors", "Barraquer needle holder"], "a": 0, "steps": ["How to recognise it: Spring handle with a locking catch; flat jaws.", "Used for: Holds needles for scleral, squint and corneal suturing.", "Viva: When is a lock useful? Larger needles and long suturing; it reduces hand fatigue."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i26", "cat": "Knives and blades", "title": "Keratome (2.2–2.8 mm)", "fields": [{"k": "knife", "tip": "keratome", "plastic": 1}], "q": "Identify this instrument.", "o": ["Keratome (2.2–2.8 mm)", "Crescent knife", "Bard-Parker handle with No. 11 blade", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Angled diamond- or trapezoid-shaped bevelled blade of a fixed width.", "Used for: Makes the main clear corneal incision in phaco.", "Viva: Square vs rectangular wound? A three-plane, longer tunnel seals better and lowers endophthalmitis risk."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i27", "cat": "Knives and blades", "title": "Crescent knife", "fields": [{"k": "knife", "tip": "crescent", "plastic": 1}], "q": "Identify this instrument.", "o": ["Crescent knife", "Keratome (2.2–2.8 mm)", "Bard-Parker handle with No. 11 blade", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Rounded, spoon-like bevel-up blade that cuts sideways.", "Used for: Makes scleral and corneal tunnels (SICS, trabeculectomy flap, MSICS).", "Viva: Plane of dissection? Lamellar, about half to two-thirds of scleral thickness."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i28", "cat": "Knives and blades", "title": "15° side-port knife", "fields": [{"k": "knife", "tip": "fifteen", "plastic": 1}], "q": "Identify this instrument.", "o": ["15° side-port knife", "Keratome (2.2–2.8 mm)", "Bard-Parker handle with No. 11 blade", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Narrow, straight blade with a 15° point.", "Used for: Makes side-port (paracentesis) incisions.", "Viva: Purpose of side ports? Second instrument entry, AC maintenance and wound hydration."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i29", "cat": "Knives and blades", "title": "MVR blade (20G)", "fields": [{"k": "knife", "tip": "mvr", "plastic": 1}], "q": "Identify this instrument.", "o": ["MVR blade (20G)", "Keratome (2.2–2.8 mm)", "Bard-Parker handle with No. 11 blade", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Lance-shaped double-edged blade.", "Used for: Sclerotomy in 20-gauge vitrectomy; entry into the eye.", "Viva: Where are sclerotomies placed? 3.5–4 mm behind the limbus in phakic eyes (pars plana)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i30", "cat": "Knives and blades", "title": "Bard-Parker handle with No. 11 blade", "fields": [{"k": "knife", "tip": "bp11", "bp": 1}], "q": "Identify this instrument.", "o": ["Bard-Parker handle with No. 11 blade", "Keratome (2.2–2.8 mm)", "MVR blade (20G)", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Flat handle with a triangular, sharp-pointed blade.", "Used for: Stab incisions: abscess drainage, DCR, lid incisions.", "Viva: Blade numbers? 11 = pointed stab, 15 = small curved, 10 = large curved."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i31", "cat": "Knives and blades", "title": "Bard-Parker handle with No. 15 blade", "fields": [{"k": "knife", "tip": "bp15", "bp": 1}], "q": "Identify this instrument.", "o": ["Bard-Parker handle with No. 15 blade", "Keratome (2.2–2.8 mm)", "MVR blade (20G)", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Flat handle with a small curved (bellied) blade.", "Used for: Skin incisions in lid, lacrimal and orbit surgery.", "Viva: Why 15 in lid surgery? Small belly gives precise curved skin cuts."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i32", "cat": "Knives and blades", "title": "Diamond knife with micrometer", "fields": [{"k": "misc", "t": "diamond"}], "q": "Identify this instrument.", "o": ["Diamond knife with micrometer", "Keratome (2.2–2.8 mm)", "MVR blade (20G)", "Trocar-cannula (23–27G)"], "a": 0, "steps": ["How to recognise it: Diamond blade with a micrometer collar to set the depth.", "Used for: Precise depth incisions: limbal relaxing incisions, radial keratotomy, refractive incisions.", "Viva: Depth for limbal relaxing incisions? Usually set to about 90% of the pachymetry."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i33", "cat": "Knives and blades", "title": "Trocar-cannula (23–27G)", "fields": [{"k": "knife", "tip": "trocar", "plastic": 1}], "q": "Identify this instrument.", "o": ["Trocar-cannula (23–27G)", "Keratome (2.2–2.8 mm)", "MVR blade (20G)", "Diamond knife with micrometer"], "a": 0, "steps": ["How to recognise it: Bevelled trocar inside a cannula with a hub.", "Used for: Creates self-sealing sclerotomy ports for small-gauge vitrectomy.", "Viva: Why an angled (oblique) entry? A beveled tunnel seals better without sutures."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i34", "cat": "Cataract surgery", "title": "Sinskey hook", "fields": [{"k": "rod", "tip": "sinskey"}], "q": "Identify this instrument.", "o": ["Sinskey hook", "Single-piece acrylic IOL", "Kuglen hook", "IOL dialing hook"], "a": 0, "steps": ["How to recognise it: Thin shaft with a small angled elbow at the tip.", "Used for: Rotates the nucleus or IOL, manipulates iris and lens.", "Viva: Use in IOL insertion? Dials the haptic into the bag."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i35", "cat": "Cataract surgery", "title": "Kuglen hook", "fields": [{"k": "rod", "tip": "kuglen"}], "q": "Identify this instrument.", "o": ["Kuglen hook", "Iris repositor", "Simcoe irrigation-aspiration cannula", "Irrigating (anterior chamber) cannula"], "a": 0, "steps": ["How to recognise it: Small curved push–pull hook at the end.", "Used for: Manipulates iris and IOL; retracts the pupil margin.", "Viva: Kuglen vs Sinskey? Kuglen has a rounded push-pull hook; Sinskey has an angled elbow."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i36", "cat": "Cataract surgery", "title": "Phaco chopper", "fields": [{"k": "rod", "tip": "chopper"}], "q": "Identify this instrument.", "o": ["Phaco chopper", "Lens loop (vectis)", "Iris hooks", "Anterior chamber IOL"], "a": 0, "steps": ["How to recognise it: Second instrument with a short right-angled tip.", "Used for: Divides the nucleus (horizontal chop) against the phaco tip.", "Viva: Chop vs divide-and-conquer? Chop uses less ultrasound energy and less stress on zonules."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i37", "cat": "Cataract surgery", "title": "Nagahara (vertical) chopper", "fields": [{"k": "rod", "tip": "nagahara"}], "q": "Identify this instrument.", "o": ["Nagahara (vertical) chopper", "Sinskey hook", "IOL dialing hook", "Cystitome"], "a": 0, "steps": ["How to recognise it: Sharp, angled chopper tip.", "Used for: Vertical chop: impales and splits a hard nucleus.", "Viva: Advantage in hard cataracts? Less phaco energy and less endothelial damage."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i38", "cat": "Cataract surgery", "title": "IOL dialing hook", "fields": [{"k": "rod", "tip": "dialer"}], "q": "Identify this instrument.", "o": ["IOL dialing hook", "Simcoe irrigation-aspiration cannula", "Irrigating (anterior chamber) cannula", "Malyugin ring"], "a": 0, "steps": ["How to recognise it: Short bend ending in a small ball or knob.", "Used for: Rotates and centres IOLs (for example aligning a toric IOL).", "Viva: How far can a toric IOL be rotated without loss? Each 1° off-axis loses about 3% of correction."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i39", "cat": "Cataract surgery", "title": "Iris repositor", "fields": [{"k": "rod", "tip": "repositor"}], "q": "Identify this instrument.", "o": ["Iris repositor", "Iris hooks", "Anterior chamber IOL", "Phaco chopper"], "a": 0, "steps": ["How to recognise it: Thin flat blade with a rounded end.", "Used for: Repositions prolapsed iris; sweeps vitreous; breaks synechiae.", "Viva: When does iris prolapse? Shallow chamber, posterior pressure or a too-posterior wound."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i40", "cat": "Cataract surgery", "title": "Cyclodialysis spatula", "fields": [{"k": "rod", "tip": "spatula"}], "q": "Identify this instrument.", "o": ["Cyclodialysis spatula", "Nagahara (vertical) chopper", "Cystitome", "Hydrodissection cannula"], "a": 0, "steps": ["How to recognise it: Flat, slightly broader spatula on a thin shaft.", "Used for: Separates tissues (iris from cornea, cyclodialysis in glaucoma, breaking adhesions).", "Viva: Cyclodialysis cleft complication? Hypotony from a large cleft."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i41", "cat": "Cataract surgery", "title": "Cystitome", "fields": [{"k": "rod", "tip": "cystitome", "short": 1}], "q": "Identify this instrument.", "o": ["Cystitome", "Irrigating (anterior chamber) cannula", "Malyugin ring", "Three-piece IOL"], "a": 0, "steps": ["How to recognise it: Bent 26G needle tip (often on a syringe or OVD cannula).", "Used for: Starts or makes the anterior capsulotomy (can-opener or CCC).", "Viva: How is it made? By bending the tip of a 26G needle."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i42", "cat": "Cataract surgery", "title": "Simcoe irrigation-aspiration cannula", "fields": [{"k": "cannula", "tip": "simcoe"}], "q": "Identify this instrument.", "o": ["Simcoe irrigation-aspiration cannula", "Anterior chamber IOL", "Phaco chopper", "Iris repositor"], "a": 0, "steps": ["How to recognise it: Two-way cannula: one tube irrigates, one aspirates, joined to a syringe.", "Used for: Manual cortex aspiration in SICS and ECCE.", "Viva: Port size for aspiration? About 0.3 mm, facing up."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i43", "cat": "Cataract surgery", "title": "Rycroft cannula (27G)", "fields": [{"k": "cannula", "tip": "rycroft"}], "q": "Identify this instrument.", "o": ["Rycroft cannula (27G)", "Cyclodialysis spatula", "Hydrodissection cannula", "Capsular tension ring"], "a": 0, "steps": ["How to recognise it: Thin angled cannula on a Luer hub.", "Used for: Injects fluid or air; hydrates wounds.", "Viva: Rycroft vs hydrodissection cannula? Hydrodissection cannulas are flattened at the tip."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i44", "cat": "Cataract surgery", "title": "Hydrodissection cannula", "fields": [{"k": "cannula", "tip": "hydro"}], "q": "Identify this instrument.", "o": ["Hydrodissection cannula", "Malyugin ring", "Three-piece IOL", "Kuglen hook"], "a": 0, "steps": ["How to recognise it: Flattened, slightly bent tip.", "Used for: Separates the nucleus from the capsule (hydrodissection) and nucleus layers (hydrodelineation).", "Viva: Risk in posterior polar cataract? Hydrodissection can rupture the weak posterior capsule; use hydrodelineation only."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i45", "cat": "Cataract surgery", "title": "Irrigating (anterior chamber) cannula", "fields": [{"k": "cannula", "tip": "cannula"}], "q": "Identify this instrument.", "o": ["Irrigating (anterior chamber) cannula", "Phaco chopper", "Iris repositor", "Simcoe irrigation-aspiration cannula"], "a": 0, "steps": ["How to recognise it: Plain blunt cannula with a slight bend.", "Used for: Irrigates the chamber, injects air or viscoelastic.", "Viva: Which fluid? Balanced salt solution (BSS)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i46", "cat": "Cataract surgery", "title": "Lens loop (vectis)", "fields": [{"k": "rod", "tip": "vectis", "thick": 1}], "q": "Identify this instrument.", "o": ["Lens loop (vectis)", "Rycroft cannula (27G)", "Capsular tension ring", "Single-piece acrylic IOL"], "a": 0, "steps": ["How to recognise it: Flat oval loop, sometimes with irrigation ports.", "Used for: Delivers the nucleus in SICS/ECCE.", "Viva: Irrigating vectis principle? Fluid pushes the nucleus out as the loop slides under it."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i47", "cat": "Cataract surgery", "title": "Capsular tension ring", "fields": [{"k": "ring", "t": "ctr"}], "q": "Identify this instrument.", "o": ["Capsular tension ring", "Three-piece IOL", "Kuglen hook", "IOL dialing hook"], "a": 0, "steps": ["How to recognise it: Open PMMA ring with an eyelet at each end.", "Used for: Supports the bag in weak zonules (pseudoexfoliation, trauma, Marfan).", "Viva: Modified (Cionni) ring? Has a fixation eyelet for scleral suturing."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i48", "cat": "Cataract surgery", "title": "Malyugin ring", "fields": [{"k": "ring", "t": "malyugin"}], "q": "Identify this instrument.", "o": ["Malyugin ring", "Iris repositor", "Simcoe irrigation-aspiration cannula", "Irrigating (anterior chamber) cannula"], "a": 0, "steps": ["How to recognise it: Square flexible ring with four scrolls.", "Used for: Expands a small pupil during cataract surgery.", "Viva: Causes of small pupil? Tamsulosin (floppy iris), pseudoexfoliation, diabetes, uveitis."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i49", "cat": "Cataract surgery", "title": "Iris hooks", "fields": [{"k": "ring", "t": "irishooks"}], "q": "Identify this instrument.", "o": ["Iris hooks", "Lens loop (vectis)", "Single-piece acrylic IOL", "Sinskey hook"], "a": 0, "steps": ["How to recognise it: Flexible wire hooks with silicone stoppers.", "Used for: Retract the iris (small pupil); support the capsule edge in zonular weakness.", "Viva: How many? Usually four, through separate limbal stab incisions."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i50", "cat": "Cataract surgery", "title": "Single-piece acrylic IOL", "fields": [{"k": "ring", "t": "iol1"}], "q": "Identify this instrument.", "o": ["Single-piece acrylic IOL", "Kuglen hook", "IOL dialing hook", "Cystitome"], "a": 0, "steps": ["How to recognise it: One piece; thick broad haptics joined to the optic.", "Used for: In-the-bag implantation through a small incision.", "Viva: Never place where? In the sulcus: chafing causes pigment dispersion, UGH syndrome."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i51", "cat": "Cataract surgery", "title": "Three-piece IOL", "fields": [{"k": "ring", "t": "iol3"}], "q": "Identify this instrument.", "o": ["Three-piece IOL", "Simcoe irrigation-aspiration cannula", "Irrigating (anterior chamber) cannula", "Malyugin ring"], "a": 0, "steps": ["How to recognise it: Thin, separate (PMMA or PVDF) haptics.", "Used for: In the bag or sulcus; optic capture in posterior capsule rupture.", "Viva: Sulcus power adjustment? Reduce by about 0.5–1.0 D."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i52", "cat": "Cataract surgery", "title": "Anterior chamber IOL", "fields": [{"k": "ring", "t": "aciol"}], "q": "Identify this instrument.", "o": ["Anterior chamber IOL", "Iris hooks", "Sinskey hook", "Nagahara (vertical) chopper"], "a": 0, "steps": ["How to recognise it: Rigid PMMA with four footplates resting in the angle.", "Used for: When there is no capsular support.", "Viva: Size by? White-to-white plus 1 mm."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i53", "cat": "Cornea, glaucoma and retina", "title": "Corneal trephine", "fields": [{"k": "rod", "tip": "trephine", "thick": 1}], "q": "Identify this instrument.", "o": ["Corneal trephine", "Castroviejo caliper", "Light pipe (endoilluminator)", "Retinal cryoprobe"], "a": 0, "steps": ["How to recognise it: Cylindrical blade on a handle, of fixed diameter.", "Used for: Cuts circular corneal buttons in keratoplasty (donor and host).", "Viva: Donor vs host size? Donor usually 0.25–0.5 mm larger."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i54", "cat": "Cornea, glaucoma and retina", "title": "Corneal punch", "fields": [{"k": "misc", "t": "punch"}], "q": "Identify this instrument.", "o": ["Corneal punch", "Silicone band and tyre (scleral buckle)", "Corneal trephine", "Vitreous cutter (vitrector)"], "a": 0, "steps": ["How to recognise it: Small punch that removes a disc of tissue.", "Used for: Punches the donor button or a peripheral iridectomy (Kelly punch) in trabeculectomy.", "Viva: Kelly punch use? Removes a block of trabecular tissue under the flap."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i55", "cat": "Cornea, glaucoma and retina", "title": "Castroviejo caliper", "fields": [{"k": "caliper"}], "q": "Identify this instrument.", "o": ["Castroviejo caliper", "Light pipe (endoilluminator)", "Retinal cryoprobe", "Rust-ring burr (Alger brush)"], "a": 0, "steps": ["How to recognise it: Two legs with a millimetre scale and screw.", "Used for: Measures and marks distances: from the limbus, incision lengths, squint surgery.", "Viva: Spiral of Tillaux? Rectus insertions at 5.5, 6.5, 6.9, 7.7 mm from the limbus (MR, IR, LR, SR)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i56", "cat": "Cornea, glaucoma and retina", "title": "Schiotz tonometer", "fields": [{"k": "schiotz"}], "q": "Identify this instrument.", "o": ["Schiotz tonometer", "Corneal trephine", "Vitreous cutter (vitrector)", "Scleral depressor"], "a": 0, "steps": ["How to recognise it: Footplate, plunger, scale and add-on weights.", "Used for: Indentation tonometry with the patient supine.", "Viva: Sources of error? Ocular rigidity (myopia, after surgery), corneal curvature."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i57", "cat": "Cornea, glaucoma and retina", "title": "Vitreous cutter (vitrector)", "fields": [{"k": "rod", "tip": "vitrector"}], "q": "Identify this instrument.", "o": ["Vitreous cutter (vitrector)", "Retinal cryoprobe", "Rust-ring burr (Alger brush)", "Castroviejo caliper"], "a": 0, "steps": ["How to recognise it: Thin probe with a side port near the closed tip.", "Used for: Cuts and removes vitreous in vitrectomy and anterior vitrectomy.", "Viva: Cut rate effect? Higher cut rates reduce traction on the retina."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i58", "cat": "Cornea, glaucoma and retina", "title": "Light pipe (endoilluminator)", "fields": [{"k": "rod", "tip": "lightpipe"}], "q": "Identify this instrument.", "o": ["Light pipe (endoilluminator)", "Schiotz tonometer", "Scleral depressor", "Corneal foreign body spud"], "a": 0, "steps": ["How to recognise it: Fine fibre-optic probe that emits light from the tip.", "Used for: Illuminates the inside of the eye during vitrectomy.", "Viva: Risk? Phototoxicity if held close to the macula for long."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i59", "cat": "Cornea, glaucoma and retina", "title": "Endolaser probe", "fields": [{"k": "rod", "tip": "laser"}], "q": "Identify this instrument.", "o": ["Endolaser probe", "Rust-ring burr (Alger brush)", "Castroviejo caliper", "Light pipe (endoilluminator)"], "a": 0, "steps": ["How to recognise it: Curved fibre-optic probe; red aiming beam.", "Used for: Retinopexy around breaks and PRP during vitrectomy.", "Viva: Wavelength? Usually 532 nm green."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i60", "cat": "Cornea, glaucoma and retina", "title": "Scleral depressor", "fields": [{"k": "rod", "tip": "depressor"}], "q": "Identify this instrument.", "o": ["Scleral depressor", "Endolaser probe", "Corneal foreign body spud", "Corneal punch"], "a": 0, "steps": ["How to recognise it: Handle with a rounded thimble-shaped tip.", "Used for: Indents the sclera to see the far retinal periphery with an indirect ophthalmoscope.", "Viva: Main use? Finding retinal breaks before detachment surgery."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i61", "cat": "Cornea, glaucoma and retina", "title": "Retinal cryoprobe", "fields": [{"k": "rod", "tip": "cryo", "thick": 1}], "q": "Identify this instrument.", "o": ["Retinal cryoprobe", "Castroviejo caliper", "Light pipe (endoilluminator)", "Silicone band and tyre (scleral buckle)"], "a": 0, "steps": ["How to recognise it: Insulated probe; tip freezes (ice ball).", "Used for: Retinopexy around breaks; cryotherapy of ROP and tumours.", "Viva: Freezing endpoint? Whitening of the retina."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i62", "cat": "Cornea, glaucoma and retina", "title": "Silicone band and tyre (scleral buckle)", "fields": [{"k": "ring", "t": "band"}], "q": "Identify this instrument.", "o": ["Silicone band and tyre (scleral buckle)", "Corneal foreign body spud", "Corneal punch", "Vitreous cutter (vitrector)"], "a": 0, "steps": ["How to recognise it: Silicone encircling band and a grooved tyre.", "Used for: Scleral buckling for rhegmatogenous retinal detachment.", "Viva: Complication? Myopic shift, diplopia, extrusion, infection."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i63", "cat": "Cornea, glaucoma and retina", "title": "Corneal foreign body spud", "fields": [{"k": "misc", "t": "spud"}], "q": "Identify this instrument.", "o": ["Corneal foreign body spud", "Light pipe (endoilluminator)", "Retinal cryoprobe", "Corneal trephine"], "a": 0, "steps": ["How to recognise it: Small blunt flattened (golf-club) tip.", "Used for: Removes superficial corneal foreign bodies.", "Viva: Alternative? A 26G needle held tangentially."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i64", "cat": "Cornea, glaucoma and retina", "title": "Rust-ring burr (Alger brush)", "fields": [{"k": "misc", "t": "burr"}], "q": "Identify this instrument.", "o": ["Rust-ring burr (Alger brush)", "Corneal punch", "Vitreous cutter (vitrector)", "Scleral depressor"], "a": 0, "steps": ["How to recognise it: Battery-driven rotating burr.", "Used for: Removes a rust ring after a metal corneal foreign body.", "Viva: When to remove? Same day or after 24–48 h when the ring softens."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i65", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Bowman lacrimal probe", "fields": [{"k": "rod", "tip": "bowman", "short": 1}], "q": "Identify this instrument.", "o": ["Bowman lacrimal probe", "Towel clip", "Lacrimal cannula", "Evisceration spoon"], "a": 0, "steps": ["How to recognise it: Thin blunt wire probe (double-ended, sized 0000 to 4).", "Used for: Probes the nasolacrimal duct in congenital NLDO.", "Viva: Best age for probing? Around 12–18 months if not resolved."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i66", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Nettleship punctum dilator", "fields": [{"k": "rod", "tip": "dilator"}], "q": "Identify this instrument.", "o": ["Nettleship punctum dilator", "Wells enucleation spoon", "Towel clip", "Lacrimal cannula"], "a": 0, "steps": ["How to recognise it: Tapering conical tip.", "Used for: Dilates the punctum before probing or syringing.", "Viva: Direction of insertion? Vertical 2 mm, then horizontal along the canaliculus."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i67", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Lacrimal cannula", "fields": [{"k": "cannula", "tip": "lacrimal"}], "q": "Identify this instrument.", "o": ["Lacrimal cannula", "Muller lacrimal sac retractor", "Wells enucleation spoon", "Towel clip"], "a": 0, "steps": ["How to recognise it: Blunt, curved cannula with a rounded tip.", "Used for: Syringing to test patency of the lacrimal drainage system.", "Viva: Reflux from the other punctum means? Block in the common canaliculus or lower down (NLD)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i68", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Muller lacrimal sac retractor", "fields": [{"k": "misc", "t": "muller"}], "q": "Identify this instrument.", "o": ["Muller lacrimal sac retractor", "Bulldog clamp", "Lacrimal cannula", "Wells enucleation spoon"], "a": 0, "steps": ["How to recognise it: Self-retaining retractor with ratchet and blunt rakes.", "Used for: Holds the wound open in DCR and other oculoplastic surgery.", "Viva: DCR success rate? About 90% for external DCR."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i69", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Kerrison bone punch", "fields": [{"k": "misc", "t": "kerrison"}], "q": "Identify this instrument.", "o": ["Kerrison bone punch", "Jameson muscle hook", "Bulldog clamp", "Lacrimal cannula"], "a": 0, "steps": ["How to recognise it: Pistol grip with an upward-biting punch at the shaft end.", "Used for: Removes bone to make the osteotomy in DCR.", "Viva: Osteotomy size? About 15 × 15 mm."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i70", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Evisceration spoon", "fields": [{"k": "rod", "tip": "spoonEvisc", "thick": 1}], "q": "Identify this instrument.", "o": ["Evisceration spoon", "Muller lacrimal sac retractor", "Jameson muscle hook", "Bulldog clamp"], "a": 0, "steps": ["How to recognise it: Sharp-edged spoon.", "Used for: Scoops out the contents of the eye in evisceration.", "Viva: Indication? Endophthalmitis or painful blind eye (not tumour)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i71", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Wells enucleation spoon", "fields": [{"k": "rod", "tip": "spoonWells", "thick": 1}], "q": "Identify this instrument.", "o": ["Wells enucleation spoon", "Bowman lacrimal probe", "Muller lacrimal sac retractor", "Jameson muscle hook"], "a": 0, "steps": ["How to recognise it: Large spoon with a central slot for the optic nerve.", "Used for: Lifts the globe forward to cut the optic nerve in enucleation.", "Viva: Enucleation indication? Intraocular tumour (retinoblastoma, melanoma), painful blind eye."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i72", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Jameson muscle hook", "fields": [{"k": "rod", "tip": "muscle", "thick": 1}], "q": "Identify this instrument.", "o": ["Jameson muscle hook", "Small tenotomy (von Graefe) hook", "Bowman lacrimal probe", "Muller lacrimal sac retractor"], "a": 0, "steps": ["How to recognise it: Large J-shaped hook with a bulb at the end.", "Used for: Hooks a rectus muscle in squint surgery.", "Viva: Why the bulb? Stops the muscle slipping off the hook."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i73", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Small tenotomy (von Graefe) hook", "fields": [{"k": "rod", "tip": "tenotomy"}], "q": "Identify this instrument.", "o": ["Small tenotomy (von Graefe) hook", "Kerrison bone punch", "Jameson muscle hook", "Bowman lacrimal probe"], "a": 0, "steps": ["How to recognise it: Smaller curved hook without a bulb.", "Used for: Picks up fine tissue and muscle edges; checks for split fibres.", "Viva: Use with Jameson hook? To sweep for missed muscle fibres after hooking."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i74", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Towel clip", "fields": [{"k": "misc", "t": "towel"}], "q": "Identify this instrument.", "o": ["Towel clip", "Nettleship punctum dilator", "Kerrison bone punch", "Jameson muscle hook"], "a": 0, "steps": ["How to recognise it: Ring handles with sharp curved points that cross.", "Used for: Secures drapes; holds tissue in oculoplasty.", "Viva: Alternative? Adhesive drapes are used more now."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i75", "cat": "Oculoplasty, lacrimal and strabismus", "title": "Bulldog clamp", "fields": [{"k": "misc", "t": "bulldog"}], "q": "Identify this instrument.", "o": ["Bulldog clamp", "Small tenotomy (von Graefe) hook", "Nettleship punctum dilator", "Kerrison bone punch"], "a": 0, "steps": ["How to recognise it: Small spring clamp with serrated jaws.", "Used for: Holds sutures or drapes; temporary occlusion.", "Viva: Why spring? Holds without a handle."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i76", "cat": "Clinic and examination", "title": "Three-mirror (Goldmann) lens", "fields": [{"k": "lens", "t": "gonio3"}], "q": "Identify this instrument.", "o": ["Three-mirror (Goldmann) lens", "Single-mirror gonioscope", "Jackson cross cylinder", "Pinhole occluder"], "a": 0, "steps": ["How to recognise it: Central lens plus three mirrors set at different angles.", "Used for: Examines the angle (gonioscopy) and the retina; laser.", "Viva: Which mirror shows the angle? The smallest, dome-shaped one (about 59°)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i77", "cat": "Clinic and examination", "title": "Single-mirror gonioscope", "fields": [{"k": "lens", "t": "gonio1"}], "q": "Identify this instrument.", "o": ["Single-mirror gonioscope", "Trial lens", "Amsler grid", "Viscoelastic (OVD) syringe"], "a": 0, "steps": ["How to recognise it: One mirror inclined to view the angle.", "Used for: Gonioscopy and laser trabeculoplasty.", "Viva: Indentation gonioscopy needs? A small four-mirror lens (Zeiss/Sussman) without coupling gel."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i78", "cat": "Clinic and examination", "title": "+20 D indirect lens", "fields": [{"k": "lens", "t": "hand", "lab": "+20 D"}], "q": "Identify this instrument.", "o": ["+20 D indirect lens", "Punctal plug", "+90 D slit-lamp lens", "Prism bar"], "a": 0, "steps": ["How to recognise it: Large double aspheric hand-held lens.", "Used for: Indirect ophthalmoscopy with the headband.", "Viva: Magnification? About ×3, field about 45°."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i79", "cat": "Clinic and examination", "title": "+90 D slit-lamp lens", "fields": [{"k": "lens", "t": "hand", "lab": "+90 D"}], "q": "Identify this instrument.", "o": ["+90 D slit-lamp lens", "Pinhole occluder", "Fluorescein strip", "Weck-Cel sponge"], "a": 0, "steps": ["How to recognise it: Small double aspheric hand-held lens.", "Used for: Fundus examination at the slit lamp.", "Viva: 78 D vs 90 D? 78 D gives more magnification; 90 D a wider field."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i80", "cat": "Clinic and examination", "title": "Jackson cross cylinder", "fields": [{"k": "lens", "t": "jcc"}], "q": "Identify this instrument.", "o": ["Jackson cross cylinder", "Viscoelastic (OVD) syringe", "Single-mirror gonioscope", "Maddox rod"], "a": 0, "steps": ["How to recognise it: Lens with plus and minus axes marked (red and white dots) on a handle.", "Used for: Refines cylinder axis and power in subjective refraction.", "Viva: Which first, axis or power? Axis first, then power."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i81", "cat": "Clinic and examination", "title": "Maddox rod", "fields": [{"k": "lens", "t": "maddox"}], "q": "Identify this instrument.", "o": ["Maddox rod", "Prism bar", "Schirmer strip", "Placido disc"], "a": 0, "steps": ["How to recognise it: Parallel red glass cylinders in a disc.", "Used for: Measures heterophoria and torsion (double Maddox rod).", "Viva: What does the patient see? A red line at 90° to the rods."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i82", "cat": "Clinic and examination", "title": "Prism bar", "fields": [{"k": "lens", "t": "prism"}], "q": "Identify this instrument.", "o": ["Prism bar", "Weck-Cel sponge", "Three-mirror (Goldmann) lens", "+90 D slit-lamp lens"], "a": 0, "steps": ["How to recognise it: A bar of prisms of increasing power.", "Used for: Measures squint with the prism cover test.", "Viva: Prism direction for esotropia? Base out."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i83", "cat": "Clinic and examination", "title": "Pinhole occluder", "fields": [{"k": "lens", "t": "pinhole"}], "q": "Identify this instrument.", "o": ["Pinhole occluder", "Jackson cross cylinder", "Trial lens", "Amsler grid"], "a": 0, "steps": ["How to recognise it: Opaque disc with one or several small holes.", "Used for: Tells refractive error from other causes of reduced vision.", "Viva: Vision worse with pinhole? Suggests macular disease or central opacity."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i84", "cat": "Clinic and examination", "title": "Trial lens", "fields": [{"k": "misc", "t": "trial"}], "q": "Identify this instrument.", "o": ["Trial lens", "Placido disc", "Punctal plug", "+20 D indirect lens"], "a": 0, "steps": ["How to recognise it: Metal-rimmed lens with a handle marked with power.", "Used for: Refraction with a trial frame.", "Viva: Sign convention? Minus lenses often have red rims; plus lenses black."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i85", "cat": "Clinic and examination", "title": "Schirmer strip", "fields": [{"k": "misc", "t": "schirmer"}], "q": "Identify this instrument.", "o": ["Schirmer strip", "+90 D slit-lamp lens", "Prism bar", "Fluorescein strip"], "a": 0, "steps": ["How to recognise it: Notched filter-paper strip with a millimetre scale.", "Used for: Measures tear production (Schirmer test).", "Viva: Normal? More than 10 mm in 5 minutes without anaesthetic."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i86", "cat": "Clinic and examination", "title": "Fluorescein strip", "fields": [{"k": "misc", "t": "fluor"}], "q": "Identify this instrument.", "o": ["Fluorescein strip", "Amsler grid", "Viscoelastic (OVD) syringe", "Single-mirror gonioscope"], "a": 0, "steps": ["How to recognise it: Paper strip with an orange fluorescein-impregnated tip.", "Used for: Stains corneal epithelial defects; tear break-up time; Seidel test; applanation.", "Viva: Seidel test positive means? Aqueous leak dilutes the dye (green stream)."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i87", "cat": "Clinic and examination", "title": "Amsler grid", "fields": [{"k": "misc", "t": "amsler"}], "q": "Identify this instrument.", "o": ["Amsler grid", "+20 D indirect lens", "Maddox rod", "Trial lens"], "a": 0, "steps": ["How to recognise it: Grid of 5 mm squares with a central dot.", "Used for: Tests central 20° of vision for distortion and scotoma (AMD, macular disease).", "Viva: Viewing distance? About 30 cm, one eye at a time with reading glasses."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i88", "cat": "Clinic and examination", "title": "Placido disc", "fields": [{"k": "misc", "t": "placido"}], "q": "Identify this instrument.", "o": ["Placido disc", "Schirmer strip", "Weck-Cel sponge", "Three-mirror (Goldmann) lens"], "a": 0, "steps": ["How to recognise it: Black and white concentric rings with a central peephole.", "Used for: Shows corneal surface regularity (keratoconus, irregular astigmatism).", "Viva: Modern version? Placido-based corneal topographers."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i89", "cat": "Clinic and examination", "title": "Weck-Cel sponge", "fields": [{"k": "misc", "t": "weck"}], "q": "Identify this instrument.", "o": ["Weck-Cel sponge", "Single-mirror gonioscope", "Jackson cross cylinder", "Pinhole occluder"], "a": 0, "steps": ["How to recognise it: Triangular cellulose sponge on a stick.", "Used for: Dries and cleans the surgical field; checks for vitreous at the wound.", "Viva: Vitreous at the wound sign? Sponge pulls a strand (vitreous wick) when touched and lifted."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i90", "cat": "Clinic and examination", "title": "Viscoelastic (OVD) syringe", "fields": [{"k": "misc", "t": "ovd"}], "q": "Identify this instrument.", "o": ["Viscoelastic (OVD) syringe", "Trial lens", "Amsler grid", "Punctal plug"], "a": 0, "steps": ["How to recognise it: Prefilled syringe with a cannula.", "Used for: Maintains the anterior chamber and protects the endothelium in cataract surgery.", "Viva: Cohesive vs dispersive? Cohesive maintains space and is removed easily; dispersive coats and protects."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}, {"id": "i91", "cat": "Clinic and examination", "title": "Punctal plug", "fields": [{"k": "misc", "t": "plug"}], "q": "Identify this instrument.", "o": ["Punctal plug", "Three-mirror (Goldmann) lens", "+90 D slit-lamp lens", "Prism bar"], "a": 0, "steps": ["How to recognise it: Small cap with a shaft (silicone or collagen).", "Used for: Blocks tear drainage in dry eye.", "Viva: Commonest complication? Extrusion; also epiphora and canaliculitis."], "pearl": "Describe in a viva: name, parts (handle, shaft, tip), material, use, and one precaution or complication."}];
